package com.ventas.integration;
import com.ventas.service.AuditService;import com.ventas.repository.AuthStore;import com.ventas.security.AuthModels.Identity;import com.ventas.dto.AuditModels.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.env.Environment;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles({"local","db"}) @Transactional @EnabledIfEnvironmentVariable(named="NEGOCIO_DB_INTEGRATION",matches="true")
class AuditDatabaseTest {
 @Autowired AuditService service;@Autowired AuthStore auth;@Autowired Environment env;@Autowired JdbcTemplate jdbc;Identity actor;String action;LocalDate day;
 @BeforeEach void setup(){var u=auth.lockUsername(env.getRequiredProperty("BOOTSTRAP_ADMIN_USUARIO")).orElseThrow();auth.context(u.username(),"INTEGRATION_ROLLBACK");actor=new Identity(u.id(),u.username(),u.nombres(),u.apellidos(),u.rol(),false,auth.permissions(u.id()),UUID.randomUUID(),OffsetDateTime.now().plusHours(1));day=jdbc.queryForObject("select timezone('America/Lima',now())::date",LocalDate.class);action="SEG.TEST_"+UUID.randomUUID().toString().substring(0,8);}
 long insert(LocalDateTime time,Long user){return jdbc.queryForObject("insert into negocio.bitacora_evento(id_usuario,accion,entidad,feccre,valor_nuevo) values(?,?,'usuario',?,?::jsonb) returning id_evento",Long.class,user,action,time,"{\"estado\":\"A\",\"password\":\"NO_PUBLICAR\",\"solicitud\":{\"cantidad\":2,\"token\":\"NO_PUBLICAR\"}}");}
 @Test void includesCurrentDayAndOrdersTiesById(){long first=insert(day.atStartOfDay(),actor.id());long last=insert(day.atTime(23,59,59),actor.id());var p=service.list(actor,new Filter(day,day,actor.usuario(),action,"SEGURIDAD",0,1));assertThat(p.total()).isEqualTo(2);assertThat(p.items()).extracting(Event::id).containsExactly(last);var second=service.list(actor,new Filter(day,day,actor.usuario(),action,"",1,1));assertThat(second.items()).extracting(Event::id).containsExactly(first);assertThat(service.list(actor,new Filter(day.minusDays(1),day.minusDays(1),"",action,"",0,25)).total()).isZero();}
 @Test void sanitizesRealJsonAndSupportsUnlinkedActor(){long id=insert(day.atTime(12,0),null);var detail=service.detail(actor,id);assertThat(detail.evento().usuario()).isEqualTo(actor.usuario());assertThat(detail.nuevo().toString()).doesNotContain("NO_PUBLICAR","password","token");assertThat(detail.nuevo().path("solicitud").path("cantidad").asInt()).isEqualTo(2);assertThat(service.options(actor).acciones()).contains(action);}
 @Test void appliesLiteralUserAndOperationFilters(){insert(day.atTime(12,0),actor.id());assertThat(service.list(actor,new Filter(null,null,"%",action,"",0,25)).total()).isZero();assertThat(service.list(actor,new Filter(null,null,"",action,"OPERACIONES",0,25)).total()).isZero();assertThat(service.list(actor,new Filter(null,null,"",action,"SEGURIDAD",0,25)).total()).isEqualTo(1);}
}
